@Composable
fun PersonalStep() {

    var pan by remember { mutableStateOf("") }
    var isPanValid by remember { mutableStateOf(false) }

    //  Auto-filled data (API se aayega)
    val fatherName = "Jamal"
    val education = "Graduate"
    val category = "OBC"

    //  Image preview state
    var showImage by remember { mutableStateOf(false) }

    // Dummy image URL (API se replace karna)
    val dummyBase64 =
        ""

    PremiumCard("Personal Information") {

        InfoRow(Icons.Default.Person, "Full Name", "Tabish Jamal")
        InfoRow(Icons.Default.DateRange, "Date of Birth", "01-01-1997")
        InfoRow(Icons.Default.Person, "Gender", "Male")

        InfoRow(Icons.Default.Person, "Father / Guardian", fatherName)
        InfoRow(Icons.Default.School, "Educational Qualification", education)

        // 🔥 CATEGORY + IMAGE BUTTON
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {

            Column(modifier = Modifier.weight(1f)) {
                Text("Category", style = MaterialTheme.typography.labelSmall)
                Text(category, fontWeight = FontWeight.Bold)
            }

            IconButton(
                onClick = { showImage = true }
            ) {
                Icon(Icons.Default.Visibility, contentDescription = null)
            }
        }

        Spacer(Modifier.height(8.dp))

        // 🔥 PAN INPUT
        PanInputField(
            pan = pan,
            onChange = {
                pan = it.uppercase()
                isPanValid = validatePAN(pan)
            },
            isValid = isPanValid
        )
    }

    //  IMAGE PREVIEW DIALOG
    if (showImage) {
        ImagePreviewDialog(
            base64Image = dummyBase64,
            onDismiss = { showImage = false }
        )
    }
}



