// ================= EMPLOYMENT =================
@Composable
fun EmploymentStep(state: LoanFormState) {

    var exp by remember { mutableStateOf("") }
    var income by remember { mutableStateOf("") }
    var employer by remember { mutableStateOf("") }
    var profession by remember { mutableStateOf("") }
    var businessName by remember { mutableStateOf("") }
    var turnover by remember { mutableStateOf("") }

    PremiumCard("Employment Details") {

        // 🔥 3 TYPE DROPDOWN
        CommonDropdown(
            label = "Occupation Type",
            options = listOf("Salaried", "Self Employed", "Business"),
            selected = state.employmentType,
            onSelect = { state.employmentType = it }
        )

        Spacer(Modifier.height(12.dp))

        // ================= SALARIED =================
        if (state.employmentType == "Salaried") {

            CommonInput(
                "Monthly Salary",
                income,
                { income = it },
                KeyboardType.Number
            )

            CommonInput(
                "Employer Name",
                employer,
                { employer = it }
            )

            CommonInput(
                "Work Experience (Years)",
                exp,
                { exp = it },
                KeyboardType.Number
            )
        }

        // ================= SELF EMPLOYED =================
        else if (state.employmentType == "Self Employed") {

            CommonInput(
                "Profession",
                profession,
                { profession = it }
            )

            CommonInput(
                "Annual Income",
                income,
                { income = it },
                KeyboardType.Number
            )

            CommonInput(
                "Experience (Years)",
                exp,
                { exp = it },
                KeyboardType.Number
            )
        }

        // ================= BUSINESS =================
        else if (state.employmentType == "Business") {

            CommonInput(
                "Business Name",
                businessName,
                { businessName = it }
            )

            CommonInput(
                "Annual Turnover",
                turnover,
                { turnover = it },
                KeyboardType.Number
            )

            CommonInput(
                "Business Experience (Years)",
                exp,
                { exp = it },
                KeyboardType.Number
            )
        }
    }
}
