// ================= OBLIGATIONS =================
@Composable
fun ObligationStep(state: LoanFormState) {

    val isHighLoan = (state.loanAmount.toIntOrNull() ?: 0) > 500000

    PremiumCard("Existing Obligations") {

        if (isHighLoan) {
            CommonInput("Existing Loans", "", {})
            CommonInput("Total EMI", "", {}, KeyboardType.Number)
            CommonInput("Credit Card Outstanding", "", {}, KeyboardType.Number)
        } else {
            Text("No obligations required for low loan amount")
        }
    }
}

